;; FIPS Montgomery multiply width K=32 with TWO parallel column accumulators:
;; products of each column alternate between accumulator A and B so the two
;; add-chains are independent and overlap on the OoO core, then A+B merge into
;; the running Comba accumulator t. ABI x0=rp x1=ap x2=bp x3=np x4=n0.
.context fips_mont (scope library) rp=x0 ap=x1 bp=x2 np=x3 n0=x4 t0=x5 t1=x6 t2=x7 m0=x8 m1=x9 plo=x10 phi=x11 q=x12 top=x14 sel=x15 rp2=x19 n02=x20 a0=x21 a1=x22 a2=x23 b0=x24 b1=x25 b2=x26
.function bn_mul_mont_fips32 export (context fips_mont)
entry:
  .save all
  sub sp, sp, #768
  mov x.rp2, x.rp
  mov x.n02, x.n0
  mov x.t0, xzr
  mov x.t1, xzr
  mov x.t2, xzr
  // col 0
  mov x.a0, xzr
  mov x.a1, xzr
  mov x.a2, xzr
  mov x.b0, xzr
  mov x.b1, xzr
